import{_ as t,o as a,c as o,a0 as d}from"./chunks/framework.l1I-fhud.js";const m=JSON.parse('{"title":"Content types","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/content-types.md","filePath":"explanation/content-types.md"}'),s={name:"explanation/content-types.md"};function r(n,e,i,c,l,p){return a(),o("div",null,[...e[0]||(e[0]=[d(`<h1 id="content-types" tabindex="-1">Content types <a class="header-anchor" href="#content-types" aria-label="Permalink to &quot;Content types&quot;">​</a></h1><p>The engine is <strong>generic</strong>: it moves <em>bytes + a manifest</em> and doesn&#39;t care what the bytes mean. A <strong>content type</strong> declares the meaning — where and how a package installs.</p><h2 id="declared-not-linked" tabindex="-1">Declared, not linked <a class="header-anchor" href="#declared-not-linked" aria-label="Permalink to &quot;Declared, not linked&quot;">​</a></h2><p>A content type is <em>data first</em>: the package&#39;s manifest names its <code>type</code> (<code>kind</code>). The manager never links a product crate. When a product must do real work (materialize a node config, enable a systemd unit), it ships a <strong>driver</strong> binary the manager launches as a subprocess — &quot;no plugin system: files&quot; (peregrin’s own ADR).</p><h2 id="the-roster" tabindex="-1">The roster <a class="header-anchor" href="#the-roster" aria-label="Permalink to &quot;The roster&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Payload</th><th>Installs into</th></tr></thead><tbody><tr><td><code>peregrin-bundle</code></td><td>workflows, <code>.node.yml</code>, <code>.snippet.yml</code>, <code>.field.yml</code>, <code>.prompt.yml</code></td><td>the peregrin bundle store</td></tr><tr><td><code>myco-config</code></td><td><code>[[kinds]]</code>, <code>[views]</code>, <code>[verbs]</code>, templates</td><td><code>myco.toml</code> / a seeded <code>project/</code></td></tr><tr><td><code>kuda-domain</code></td><td><code>data/domains/*.toml</code></td><td><code>.kuda/domains/</code></td></tr><tr><td><code>mimus-rules</code></td><td><code>rules/*.toml</code></td><td><code>rules/</code></td></tr><tr><td><code>files</code></td><td>anything</td><td>the store entry (no driver)</td></tr></tbody></table><p>Adding a type is a new <code>tamias-driver-&lt;type&gt;</code> binary — never a change to the engine.</p><h2 id="drivers" tabindex="-1">Drivers <a class="header-anchor" href="#drivers" aria-label="Permalink to &quot;Drivers&quot;">​</a></h2><p>The engine is generic — it moves <em>bytes + a manifest</em> and unpacks into the store. Everything product-specific beyond that is a <strong>driver</strong>: when a package&#39;s <code>type:</code> isn&#39;t <code>files</code>, tamias resolves a <code>tamias-driver-&lt;type&gt;</code> executable — on <code>PATH</code> or in <code>&lt;tamias-home&gt;/drivers/</code> — and runs it as a subprocess:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tamias-driver-&lt;type&gt; install --dir &lt;payload&gt; --name &lt;name&gt; [--config &lt;file&gt;]</span></span>
<span class="line"><span>tamias-driver-&lt;type&gt; deploy   --dir &lt;dir&gt;     --name &lt;name&gt; [--config &lt;file&gt;]</span></span>
<span class="line"><span>tamias-driver-&lt;type&gt; uninstall --dir &lt;dir&gt;    --name &lt;name&gt;</span></span>
<span class="line"><span>tamias-driver-&lt;type&gt; capabilities            # → {&quot;types&quot;:[…]}</span></span></code></pre></div><p>The driver owns the product&#39;s schema — where it materializes, what &quot;deployed&quot; means, how to tear down. tamias never learns it. Drivers built on <code>pavo-driver-kit</code> additionally answer the pavo surface (<code>manifest</code>/<code>serve</code>/<code>ops</code>/<code>run</code>) — views plus an ops manifest of bounded verbs for generated clients; see <a href="/tamias/how-to/write-a-driver.html#beyond-the-lifecycle-pavo-surfaces">Write a driver</a>.</p><p>A package can <strong>ship its own driver</strong> under <code>drivers/</code> in the payload; installing registers it into <code>&lt;tamias-home&gt;/drivers/</code>. Because that&#39;s arbitrary code, it requires <code>--allow-drivers</code> / <code>TAMIAS_ALLOW_DRIVERS=1</code> — see <a href="/tamias/explanation/security.html">Security model</a>.</p><p><code>files</code> is the built-in type: the store entry is the whole story, no driver needed. Any other type <strong>fails to install</strong> without a discoverable driver — fail closed, never silent.</p><p><code>tamias drivers</code> lists every discovered driver (PATH + <code>&lt;tamias-home&gt;/drivers/</code>) with its <code>capabilities</code> answer — types, verbs, location — the same scan <code>doctor</code> summarizes.</p><p>See <a href="/tamias/how-to/write-a-driver.html">Write a driver</a> for the authoring side.</p>`,15)])])}const g=t(s,[["render",r]]);export{m as __pageData,g as default};
